create table RB_BASE_ACCT (BASE_ACCT_NO VARCHAR(50) not null  ,CLIENT_NO VARCHAR(22) not null  ,CLIENT_TYPE VARCHAR(3) null  ,DOCUMENT_ID VARCHAR(40) null  ,DOCUMENT_TYPE VARCHAR(6) null  ,ISS_COUNTRY VARCHAR(3) null  ,CARD_NO VARCHAR(19) null  ,SOURCE_TYPE VARCHAR(10) null  ,PROD_TYPE VARCHAR(20) null  ,ACCT_CCY VARCHAR(3) null  ,ACCT_BRANCH VARCHAR(30) null  ,ACCT_OPEN_DATE TIMESTAMP(3) null  ,ACCT_TYPE VARCHAR(1) null  ,ACCT_NAME VARCHAR(100) null  ,ALT_ACCT_NAME VARCHAR(100) null  ,ACCT_STATUS VARCHAR(1) null  ,ACCT_STATUS_PREV VARCHAR(1) null  ,ACCT_STATUS_UPD_DATE TIMESTAMP(3) null  ,ACCT_CLOSE_REASON VARCHAR(200) null  ,ACCT_CLOSE_USER_ID VARCHAR(30) null  ,ACCT_DESC VARCHAR(100) null  ,ACCT_RES_STATUS VARCHAR(1) null  ,OLD_PROD_TYPE VARCHAR(20) null  ,TERMINAL_ID VARCHAR(60) null  ,ACCT_EXEC VARCHAR(100) null  ,USER_ID VARCHAR(30) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,LAST_CHANGE_USER_ID VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,ALL_DRA_IND VARCHAR(1) null  ,ALL_DEP_IND VARCHAR(1) null  ,ACCT_CLOSE_DATE TIMESTAMP(3) null  ,SOURCE_MODULE VARCHAR(2) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(BASE_ACCT_NO,CLIENT_NO));